"""Deterministic bid arithmetic for the RFQ-to-bid challenge.

The agents find and select the evidence; this module only applies the bid rules of the task brief to the structured
facts they filed: exact Decimal arithmetic, ROUND_HALF_UP to the cent, largest-remainder cent allocation, marginal
bonus bands, shared stock and delivery commitments. It contains no scenario values and never touches a website.
"""
from __future__ import annotations

import math
import re
from dataclasses import dataclass, field, replace
from datetime import datetime, timedelta, timezone
from decimal import Decimal, InvalidOperation, ROUND_FLOOR, ROUND_HALF_UP

CENT = Decimal("0.01")
ZERO = Decimal("0")
HUNDRED = Decimal("100")

# Mass units to grams and index-rate units to EUR per gram, so any combination the sources use multiplies out.
MASS_TO_GRAMS = {"mg": Decimal("0.001"), "g": Decimal(1), "kg": Decimal(1000), "t": Decimal(1000000)}


def round_cents(value) -> Decimal:
    return Decimal(str(value)).quantize(CENT, rounding=ROUND_HALF_UP)


def parse_number(raw, number_format: str | None = None) -> Decimal | None:
    """A number as written on a page ("1.234,56", "64,853 (en-US)", 12) as a Decimal; None when there is none.

    `number_format` is "de-DE" (decimal comma) or "en-US" (decimal point); an inline tag in `raw` wins. Without
    either, the separators decide, and a lone comma is read as a decimal comma, as German sources write it.
    """
    if raw is None or isinstance(raw, bool):
        return None
    if isinstance(raw, Decimal):
        return raw
    if isinstance(raw, (int, float)):
        return Decimal(str(raw))
    text = str(raw).strip()
    tag = re.search(r"(de-DE|en-US)", text, re.IGNORECASE)
    fmt = (tag.group(1) if tag else number_format or "").lower()
    match = re.search(r"[-+]?\d[\d.,'\s  ]*", text)
    if not match:
        return None
    token = re.sub(r"['\s  ]", "", match.group(0)).rstrip(".,")
    try:
        if fmt == "en-us":
            return Decimal(token.replace(",", ""))
        if fmt == "de-de":
            return Decimal(token.replace(".", "").replace(",", "."))
        if "," in token and "." in token:
            if token.rfind(",") > token.rfind("."):
                return Decimal(token.replace(".", "").replace(",", "."))
            return Decimal(token.replace(",", ""))
        if "," in token:
            return Decimal(token.replace(",", ".")) if token.count(",") == 1 else Decimal(token.replace(",", ""))
        if token.count(".") > 1:
            return Decimal(token.replace(".", ""))
        return Decimal(token)
    except InvalidOperation:
        return None


def parse_when(raw, end_of_day: bool = False) -> datetime | None:
    """An ISO 8601 date or timestamp (as the extraction step writes them) as an aware UTC datetime.

    A value without a time is a whole day: its start, or its last microsecond with `end_of_day`, so that validity
    periods include both endpoints.
    """
    if not raw:
        return None
    text = str(raw).strip()
    try:
        if re.fullmatch(r"\d{4}-\d{2}-\d{2}", text):
            day = datetime.fromisoformat(text).replace(tzinfo=timezone.utc)
            return day + timedelta(days=1) - timedelta(microseconds=1) if end_of_day else day
        when = datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError:
        german = re.search(r"(\d{1,2})\.(\d{1,2})\.(\d{4})(?:[,\s]+(\d{1,2}):(\d{2}))?", text)
        if not german:
            return None
        day, month, year, hour, minute = german.groups()
        when = datetime(int(year), int(month), int(day), int(hour or 0), int(minute or 0))
        if hour is None and end_of_day:
            when += timedelta(days=1) - timedelta(microseconds=1)
    return when.replace(tzinfo=timezone.utc) if when.tzinfo is None else when.astimezone(timezone.utc)


def allocate_cents(total_cents: int, weights: dict[str, Decimal], method: str = "largest_remainder") -> dict[str, Decimal]:
    """Split `total_cents` across the keys in proportion to `weights`, as EUR amounts that sum exactly.

    Every share is floored to the cent; the cents left over go out by `method`: "largest_remainder" (ties to the
    lower key), "remainder_to_first", "remainder_to_last" or "remainder_to_largest" (the biggest weight).
    """
    keys = sorted(weights)
    total_weight = sum(weights.values(), ZERO)
    if not keys or total_cents <= 0 or total_weight <= 0:
        return {key: ZERO for key in keys}
    exact = {key: Decimal(total_cents) * weights[key] / total_weight for key in keys}
    cents = {key: int(exact[key].to_integral_value(rounding=ROUND_FLOOR)) for key in keys}
    left = total_cents - sum(cents.values())
    if method == "remainder_to_first":
        cents[keys[0]] += left
    elif method == "remainder_to_last":
        cents[keys[-1]] += left
    elif method == "remainder_to_largest":
        cents[max(keys, key=lambda key: (weights[key], -keys.index(key)))] += left
    else:
        for key in sorted(keys, key=lambda key: (-(exact[key] - cents[key]), key))[:left]:
            cents[key] += 1
    return {key: Decimal(cents[key]) * CENT for key in keys}


def same_text(a: str | None, b: str | None) -> bool:
    """Two attribute values name the same thing: case, spacing and punctuation aside."""
    def norm(value):
        return re.sub(r"[^0-9a-zäöüß]+", "", (value or "").lower())
    return norm(a) == norm(b)


NO_CERTIFICATE = ("", "-", "keine", "kein", "ohne", "none", "no", "n/a", "na", "nicht gefordert", "keine gefordert",
                  "nicht erforderlich", "keine erforderlich", "entfällt")


def same_certification(a: str | None, b: str | None) -> bool:
    """Certifications match, with every way of writing "none required" counting as the same."""
    def norm(value):
        text = re.sub(r"\s+", " ", (value or "").strip().lower()).strip(" .—–")
        return "" if text in NO_CERTIFICATE else text
    return same_text(norm(a), norm(b))


@dataclass
class Position:
    position: str
    requirement_ref: str
    quantity: int
    is_set: bool = False  # the quantity counts sets, not pieces
    description: str = ""


@dataclass
class Clarification:
    """One answer of the tender's Q&A, as far as it changes the bid."""
    number: str
    when: datetime | None
    withdraws: list[str] = field(default_factory=list)
    quantity_changes: list[tuple[str, int, bool | None]] = field(default_factory=list)  # position, quantity, is_set
    amendments: list[tuple[str, str, str, str]] = field(default_factory=list)  # revision, requirement, attribute, value
    assignments: dict[str, dict[str, str]] = field(default_factory=dict)  # position -> {kind: key}
    setup_fees: dict[str, Decimal] = field(default_factory=dict)  # position -> ordinary setup fee, EUR


@dataclass
class Requirement:
    ref: str
    bore_mm: int | None = None
    stroke_mm: int | None = None
    pressure_bar: int | None = None
    mounting: str | None = None
    certification: str | None = None
    catalogue_group: str | None = None
    usable_travel: bool = False  # the stroke is the usable travel: add twice the per-end reserve
    reserve_key: str | None = None
    pieces_per_set: int | None = None

    def missing(self) -> list[str]:
        return [name for name in ("bore_mm", "stroke_mm", "pressure_bar", "mounting") if getattr(self, name) is None]


@dataclass
class PriceCondition:
    valid_from: datetime | None
    valid_to: datetime | None
    currency: str = "EUR"
    fx_key: str | None = None
    price_unit: int = 1  # the scale prices are for this many pieces
    scales: list[tuple[int, Decimal]] = field(default_factory=list)  # minimum quantity, price

    def valid_on(self, when: datetime) -> bool:
        return (self.valid_from is None or self.valid_from <= when) and (self.valid_to is None or when <= self.valid_to)


@dataclass
class Material:
    number: str
    active: bool | None = None
    catalogue_group: str | None = None
    bore_mm: int | None = None
    stroke_mm: int | None = None
    pressure_bar: int | None = None
    mounting: str | None = None
    certification: str | None = None
    carton_size: int | None = None
    allocation_mass_g: Decimal | None = None
    surcharge_mass_g: Decimal | None = None
    index_code: str | None = None
    stock: int | None = None
    stock_lead_weeks: int | None = None
    production_lead_weeks: int | None = None
    conditions: list[PriceCondition] = field(default_factory=list)

    def matches(self, need: Requirement) -> bool:
        return (self.bore_mm == need.bore_mm and self.stroke_mm == need.stroke_mm
                and self.pressure_bar == need.pressure_bar and same_text(self.mounting, need.mounting)
                and same_certification(self.certification, need.certification))


@dataclass
class Commitment:
    material: str
    weeks: int
    max_quantity: int | None


@dataclass
class BonusBand:
    lower: Decimal
    upper: Decimal | None  # None: no upper limit
    percent: Decimal


@dataclass
class Authorities:
    """What the authorized records say, each key already resolved to its latest applicable record."""
    discount_percent: Decimal | None = None  # None: no approval
    discount_min_order: Decimal | None = None
    clauses: dict[str, str] = field(default_factory=dict)  # group -> base_only | base_and_surcharge | none
    index_rates: dict[str, Decimal] = field(default_factory=dict)  # code -> EUR per gram
    reserves: dict[str, tuple[str | None, int]] = field(default_factory=dict)  # key -> (revision, mm per end)
    tariffs: dict[str, Decimal] = field(default_factory=dict)  # key -> EUR per carton
    commitments: dict[str, Commitment] = field(default_factory=dict)
    fx: dict[str, Decimal] = field(default_factory=dict)  # key -> EUR per currency unit
    pools: dict[str, tuple[Decimal, str]] = field(default_factory=dict)  # key -> (fee EUR, allocation method)
    bonus: dict[str, list[BonusBand]] = field(default_factory=dict)


@dataclass
class Line:
    position: str
    material_number: str
    quantity: int
    unit_price: Decimal | None = None
    lead_time_weeks: int | None = None
    base_unit_price: Decimal | None = None
    surcharge_per_unit: Decimal | None = None
    packaging_per_unit: Decimal | None = None
    rebate_total: Decimal | None = None
    material: Material | None = None
    gaps: list[str] = field(default_factory=list)  # what kept a field from being worked out


@dataclass
class Bid:
    tender_reference: str
    decision: str
    discount_percent: Decimal
    lines: list[Line]
    total_net: Decimal
    omitted: list[str] = field(default_factory=list)  # positions that could not be priced
    notes: list[str] = field(default_factory=list)

    def answer(self) -> dict:
        def number(value):
            return int(value) if value == value.to_integral_value() else float(value)
        positions = []
        for line in self.lines:
            entry = {"position": line.position, "material_number": line.material_number, "quantity": line.quantity,
                     "unit_price": float(line.unit_price), "lead_time_weeks": line.lead_time_weeks}
            for name in ("base_unit_price", "surcharge_per_unit", "packaging_per_unit", "rebate_total"):
                if getattr(line, name) is not None:
                    entry[name] = float(getattr(line, name))
            positions.append(entry)
        return {"tender_reference": self.tender_reference, "decision": self.decision, "currency": "EUR",
                "discount_percent": number(self.discount_percent), "positions": positions,
                "total_net": float(self.total_net)}


def active_clarifications(clarifications: list[Clarification], scenario: datetime) -> list[Clarification]:
    """The answers that count, oldest first: dated no later than the scenario date and not withdrawn by another."""
    dated = [c for c in clarifications if c.when is None or c.when <= scenario]
    withdrawn = {str(number).strip() for c in dated for number in c.withdraws}
    floor = datetime.min.replace(tzinfo=timezone.utc)
    return sorted((c for c in dated if c.number.strip() not in withdrawn), key=lambda c: (c.when or floor, c.number))


def resolve_requirements(requirements: dict[str, Requirement], governing_revision: str | None,
                         answers: list[Clarification], authorities: Authorities) -> tuple[dict[str, Requirement], dict[str, str]]:
    """The governing requirements after scoped amendments and the usable-travel derivation.

    Returns them with, per requirement that still waits for a reserve, what it waits for.
    """
    resolved = {ref: replace(need) for ref, need in requirements.items()}
    for answer in answers:  # oldest first, so the latest amendment wins per attribute
        for revision, ref, attribute, value in answer.amendments:
            need = resolved.get(ref)
            if need is None or not governing_revision or not same_text(revision, governing_revision):
                continue
            name = attribute.lower()
            number = parse_number(value)
            if name in ("stroke", "bore", "pressure") and number is not None:
                setattr(need, {"stroke": "stroke_mm", "bore": "bore_mm", "pressure": "pressure_bar"}[name], int(number))
            elif name in ("mounting", "certification"):
                setattr(need, name, str(value).strip())
    waiting: dict[str, str] = {}
    for ref, need in resolved.items():
        if not need.usable_travel or need.stroke_mm is None:
            continue
        entry = authorities.reserves.get(need.reserve_key or "")
        if entry is None and not need.reserve_key:  # the release may name only the revision
            bound = [e for e in authorities.reserves.values() if e[0] and same_text(e[0], governing_revision)]
            entry = bound[0] if len(bound) == 1 else None
        if entry is None or (entry[0] and governing_revision and not same_text(entry[0], governing_revision)):
            waiting[ref] = need.reserve_key or "the per-end reserve"
            continue
        need.stroke_mm += 2 * entry[1]
        need.usable_travel = False
    return resolved, waiting


def final_quantities(positions: list[Position], answers: list[Clarification],
                     requirements: dict[str, Requirement]) -> tuple[dict[str, int], list[str]]:
    """Each position's quantity in pieces: the tender's, replaced by the latest answer that changes it, sets
    converted with the requirement's pieces per set. Also the positions whose set size is unknown."""
    raw = {p.position: (p.quantity, p.is_set) for p in positions}
    for answer in answers:
        for position, quantity, is_set in answer.quantity_changes:
            if position in raw:
                raw[position] = (quantity, raw[position][1] if is_set is None else is_set)
    pieces, unknown = {}, []
    for p in positions:
        quantity, is_set = raw[p.position]
        if is_set:
            need = requirements.get(p.requirement_ref)
            if need is None or not need.pieces_per_set:
                unknown.append(p.position)
                continue
            quantity *= need.pieces_per_set
        pieces[p.position] = quantity
    return pieces, unknown


def match_material(need: Requirement, materials: list[Material]) -> Material | None:
    """The active material that equals the requirement in every attribute; its catalogue group first."""
    exact = [m for m in materials if m.active and m.matches(need)]
    grouped = [m for m in exact if need.catalogue_group and same_text(m.catalogue_group, need.catalogue_group)]
    return (grouped or exact or [None])[0]


def merged_assignments(answers: list[Clarification]) -> tuple[dict[str, dict[str, str]], dict[str, Decimal]]:
    keys: dict[str, dict[str, str]] = {}
    fees: dict[str, Decimal] = {}
    for answer in answers:
        for position, assigned in answer.assignments.items():
            keys.setdefault(position, {}).update({kind: key for kind, key in assigned.items() if key})
        fees.update(answer.setup_fees)
    return keys, fees


def base_price(material: Material, quantity: int, scenario: datetime, authorities: Authorities) -> tuple[Decimal | None, str]:
    """The EUR base price per piece: the condition valid on the scenario date, the highest scale reached, the price
    unit normalised, converted with the condition's FX key and rounded to the cent."""
    valid = [c for c in material.conditions if c.scales and c.valid_on(scenario)]
    if not valid:
        return None, "no price condition valid on the scenario date"
    condition = valid[0]
    reached = [scale for scale in condition.scales if scale[0] <= quantity]
    if not reached:
        return None, "the quantity is below the lowest price scale"
    price = max(reached, key=lambda scale: scale[0])[1] / Decimal(condition.price_unit or 1)
    if condition.currency.upper() != "EUR":
        rate = authorities.fx.get(condition.fx_key or "")
        if rate is None:
            return None, f"no FX fixing for {condition.fx_key or condition.currency}"
        price *= rate
    return round_cents(price), ""


def calculate_bid(tender_reference: str, scenario: datetime, governing_revision: str | None,
                  positions: list[Position], clarifications: list[Clarification],
                  requirements: dict[str, Requirement], materials: list[Material], authorities: Authorities,
                  no_material: set[str] | None = None) -> Bid:
    """Apply the bid rules. `no_material` names the requirements the agents searched without finding an active
    match: one of them makes the answer a no_bid. Positions that lack evidence are left out (partial bid)."""
    answers = active_clarifications(clarifications, scenario)
    needs, waiting = resolve_requirements(requirements, governing_revision, answers, authorities)
    quantities, unknown_sets = final_quantities(positions, answers, needs)
    assigned, setup_fees = merged_assignments(answers)
    notes: list[str] = []
    omitted: list[str] = []

    lines: dict[str, Line] = {}
    for p in sorted(positions, key=lambda p: p.position):
        need = needs.get(p.requirement_ref)
        if need is not None and p.requirement_ref not in waiting and not need.missing():
            material = match_material(need, materials)
            if material is None and p.requirement_ref in (no_material or set()):
                approved = authorities.discount_percent or ZERO
                conditional = bool(authorities.discount_min_order)
                return Bid(tender_reference, "no_bid", ZERO if conditional else approved, [], ZERO,
                           notes=[f"no active material matches requirement {p.requirement_ref} (position {p.position})"])
        else:
            material = None
        if material is None or p.position not in quantities:
            omitted.append(p.position)
            notes.append(f"position {p.position}: " + ("set size unknown" if p.position in unknown_sets
                                                       else f"no material resolved for {p.requirement_ref}"))
            continue
        lines[p.position] = Line(p.position, material.number, quantities[p.position], material=material)

    for line in list(lines.values()):
        line.base_unit_price, why = base_price(line.material, line.quantity, scenario, authorities)
        if line.base_unit_price is None:
            notes.append(f"position {line.position}: {why}")
            omitted.append(line.position)
            del lines[line.position]

    # The approval's threshold looks at the undiscounted goods value: quantities times EUR base prices.
    goods = {key: round_cents(Decimal(line.quantity) * line.base_unit_price) for key, line in lines.items()}
    order_value = round_cents(sum((Decimal(l.quantity) * l.base_unit_price for l in lines.values()), ZERO))
    discount = authorities.discount_percent or ZERO
    if discount and authorities.discount_min_order is not None and order_value < authorities.discount_min_order:
        discount = ZERO
        notes.append("the conditional discount approval misses its minimum order value")
    factor = (HUNDRED - discount) / HUNDRED

    def members(kind: str, known) -> dict[str, list[str]]:
        groups: dict[str, list[str]] = {}
        for key in lines:
            assigned_key = assigned.get(key, {}).get(kind)
            if assigned_key and assigned_key in known:
                groups.setdefault(assigned_key, []).append(key)
        return groups

    pool_share = {key: ZERO for key in lines}
    for pool, keys in members("setup_pool", authorities.pools).items():
        fee, method = authorities.pools[pool]
        weights = {key: Decimal(lines[key].quantity) * (lines[key].material.allocation_mass_g or ZERO) for key in keys}
        if any(weight <= 0 for weight in weights.values()):
            for key in keys:
                lines[key].gaps.append("allocation mass")
            continue
        for key, share in allocate_cents(int(round_cents(fee) * 100), weights, method).items():
            pool_share[key] += share

    rebate = {key: ZERO for key in lines}
    for plan, keys in members("project_bonus", authorities.bonus).items():
        eligible = sum((goods[key] for key in keys), ZERO)
        credit = ZERO
        for band in authorities.bonus[plan]:
            top = eligible if band.upper is None else min(eligible, band.upper)
            if top > band.lower:
                credit += (top - band.lower) * band.percent / HUNDRED
        shares = allocate_cents(int(round_cents(credit) * 100), {key: goods[key] for key in keys})
        for key, share in shares.items():
            rebate[key] += share

    demand: dict[str, int] = {}
    for line in lines.values():
        demand[line.material_number] = demand.get(line.material_number, 0) + line.quantity

    for key, line in lines.items():
        material, quantity, keys = line.material, Decimal(line.quantity), assigned.get(key, {})
        unassigned = [kind for kind in ("packaging_tariff", "setup_pool", "project_bonus", "delivery_commitment",
                                        "condition_group") if keys.get(kind) and keys[kind] not in
                      {"packaging_tariff": authorities.tariffs, "setup_pool": authorities.pools,
                       "project_bonus": authorities.bonus, "delivery_commitment": authorities.commitments,
                       "condition_group": authorities.clauses}[kind]]
        line.gaps.extend(f"{kind} {keys[kind]}" for kind in unassigned)

        surcharge = ZERO  # the mass surcharge per piece, unrounded
        if material.index_code:
            rate = authorities.index_rates.get(material.index_code)
            if rate is None or material.surcharge_mass_g is None:
                line.gaps.append(f"metal index {material.index_code}")
            else:
                surcharge = material.surcharge_mass_g * rate
        setup = setup_fees.get(key, ZERO) + pool_share[key]

        cartons = ZERO
        if keys.get("packaging_tariff") in authorities.tariffs:
            if material.carton_size:
                cartons = Decimal(math.ceil(line.quantity / material.carton_size)) * authorities.tariffs[keys["packaging_tariff"]]
            else:
                line.gaps.append("carton size")

        clause = authorities.clauses.get(keys.get("condition_group") or "", "base_only")
        base = line.base_unit_price * (factor if clause in ("base_only", "base_and_surcharge") else 1)
        mass = surcharge * (factor if clause == "base_and_surcharge" else 1)
        line.unit_price = round_cents(base + mass + (setup + cartons - rebate[key]) / quantity)

        blocked = " ".join(line.gaps)
        line.surcharge_per_unit = None if "metal index" in blocked or "setup_pool" in blocked or "allocation mass" in blocked \
            else round_cents(surcharge + setup / quantity)
        line.packaging_per_unit = None if "packaging_tariff" in blocked or "carton size" in blocked \
            else round_cents(cartons / quantity)
        line.rebate_total = None if "project_bonus" in blocked else round_cents(rebate[key])

        pooled = demand[line.material_number]
        commitment = authorities.commitments.get(keys.get("delivery_commitment") or "")
        if commitment and same_text(commitment.material, line.material_number) and (
                commitment.max_quantity is None or pooled <= commitment.max_quantity):
            line.lead_time_weeks = commitment.weeks
        elif material.stock is not None and material.stock >= pooled and material.stock_lead_weeks is not None:
            line.lead_time_weeks = material.stock_lead_weeks
        else:
            line.lead_time_weeks = material.production_lead_weeks
            if material.stock is None:
                line.gaps.append("stock")
        if line.lead_time_weeks is None:
            line.lead_time_weeks = material.stock_lead_weeks or 0
            line.gaps.append("lead time")
        if line.gaps:
            notes.append(f"position {key}: unresolved {', '.join(line.gaps)}")

    ordered = [lines[key] for key in sorted(lines)]
    total = round_cents(sum((Decimal(line.quantity) * line.unit_price for line in ordered), ZERO))
    return Bid(tender_reference, "bid", discount, ordered, total, omitted=sorted(set(omitted)), notes=notes)

"""What an agent sees of a browser tab and what it can do there.

`Tab.observe()` renders any web page as accessible text: what a screen reader would announce, with every control
numbered so the model can act on it. Nothing here knows a particular website. It reads labels, descriptions,
tooltips, embedded frames and collapsed sections, drops invisible characters, and leaves every choice of where to go
and what to read to the model.
"""
from __future__ import annotations

import asyncio
import io
import re
import zipfile
from html.parser import HTMLParser
from urllib.parse import urljoin, urlparse

# Renders one document. Returns {text, next}: `text` with ⟦FRAME:n⟧ markers where embedded documents go, `next` the
# first unused element id. Every control gets data-aid="<id>" so it can be found again.
SNAPSHOT_JS = r"""
(startId) => {
  const ZW = /[​-‏⁠-⁤﻿­͏؜᠎]/g;
  const SKIP = new Set(['SCRIPT','STYLE','NOSCRIPT','TEMPLATE','HEAD','META','LINK','TITLE','OPTION','OPTGROUP',
                        'DATALIST','SOURCE','TRACK','PARAM']);
  const CONTROL = new Set(['INPUT','SELECT','TEXTAREA','BUTTON']);
  let nextId = startId;
  document.querySelectorAll('[data-aid]').forEach(e => e.removeAttribute('data-aid'));
  const described = new Set();
  document.querySelectorAll('[aria-describedby],[aria-labelledby]').forEach(e => {
    ((e.getAttribute('aria-describedby') || '') + ' ' + (e.getAttribute('aria-labelledby') || ''))
      .split(/\s+/).forEach(id => id && described.add(id));
  });
  const clean = s => (s || '').replace(ZW, '').replace(/\s+/g, ' ').trim();
  const cut = (s, n) => s.length > n ? s.slice(0, n) + '…' : s;
  const styleOf = el => getComputedStyle(el);
  const cssHidden = el => { const cs = styleOf(el); return cs.display === 'none' || cs.visibility === 'hidden' || cs.visibility === 'collapse'; };
  const isHidden = el => el.hidden || el.getAttribute('aria-hidden') === 'true' || (el.tagName === 'INPUT' && el.type === 'hidden') || cssHidden(el);
  const pseudo = (el, which) => {
    let c; try { c = getComputedStyle(el, which).content; } catch (e) { return ''; }
    if (!c || c === 'none' || c === 'normal') return '';
    const attr = c.match(/^attr\(([^)]+)\)$/);
    if (attr) return el.getAttribute(attr[1].trim()) || '';
    const quoted = c.match(/^"((?:[^"\\]|\\.)*)"$/) || c.match(/^'((?:[^'\\]|\\.)*)'$/);
    return quoted ? quoted[1].replace(/\\(.)/g, '$1') : '';
  };
  const reversed = el => { const cs = styleOf(el); return cs.direction === 'rtl' && /bidi-override/.test(cs.unicodeBidi); };
  // The text a screen reader would read for a subtree. `force` reads a hidden root (tooltips, descriptions).
  const textOf = (node, force) => {
    if (node.nodeType === 3) return node.nodeValue;
    if (node.nodeType !== 1 || SKIP.has(node.tagName)) return '';
    if (!force && isHidden(node)) return '';
    const label = node.getAttribute('aria-label');
    const role = node.getAttribute('role');
    const tag = node.tagName.toUpperCase();
    if (label && (role === 'img' || tag === 'CANVAS' || tag === 'SVG' || tag === 'IMG')) return ' ' + label + ' ';
    if (tag === 'IMG') return ' ' + (node.getAttribute('alt') || '') + ' ';
    if (tag === 'BR') return '\n';
    if (CONTROL.has(tag) && tag !== 'BUTTON') return '';
    let s = pseudo(node, '::before');
    for (const child of node.childNodes) s += textOf(child, false);
    s += pseudo(node, '::after');
    if (reversed(node)) s = [...s].reverse().join('');
    return s;
  };
  const byIds = ids => clean((ids || '').split(/\s+/).map(id => { const e = id && document.getElementById(id); return e ? textOf(e, true) : ''; }).join(' '));
  const nameOf = el => clean(byIds(el.getAttribute('aria-labelledby')) || textOf(el, false) || el.getAttribute('aria-label') || el.getAttribute('title') || el.getAttribute('value') || '');
  const labelOf = el => {
    const parts = [byIds(el.getAttribute('aria-labelledby')), el.getAttribute('aria-label') || ''];
    if (el.labels) for (const l of el.labels) parts.push(textOf(l, false));
    let s = clean(parts.join(' '));
    if (!s) s = clean(el.getAttribute('placeholder') || el.getAttribute('title') || el.getAttribute('name') || '');
    return s;
  };
  const disabled = el => el.disabled === true || el.getAttribute('aria-disabled') === 'true' || !!el.closest('fieldset[disabled],[inert]');
  const dataHints = el => {
    const out = [];
    for (const a of el.attributes) {
      if (!a.name.startsWith('data-') || a.name === 'data-aid' || out.length >= 3) continue;
      out.push(a.value ? a.name + '=' + cut(clean(a.value), 60) : a.name);
    }
    return out.length ? ' {' + out.join(' ') + '}' : '';
  };
  const hrefOf = el => {
    const raw = el.getAttribute('href') || '';
    try { const u = new URL(raw, location.href); return u.origin === location.origin ? u.pathname + u.search + u.hash : u.href; }
    catch (e) { return raw; }
  };
  const q = s => '"' + cut(clean(s), 160).replace(/"/g, "'") + '"';
  const flags = el => (disabled(el) ? ' (disabled)' : '') + (el.required ? ' (required)' : '') + (el.readOnly ? ' (read-only)' : '');
  const descr = el => { const d = byIds(el.getAttribute('aria-describedby')); return d ? ' (described: ' + q(d) + ')' : ''; };
  const tag = (el, collapsed) => { const id = nextId++; el.setAttribute('data-aid', String(id)); return '[' + id + ']' + (collapsed ? ' (in collapsed menu)' : ''); };
  // One control as text, or null when `el` is not a control.
  const control = (el, collapsed) => {
    const t = el.tagName.toUpperCase(), role = el.getAttribute('role') || '', type = (el.getAttribute('type') || '').toLowerCase();
    if (t === 'A' && el.hasAttribute('href')) return tag(el, collapsed) + ' link ' + q(nameOf(el)) + ' -> ' + cut(hrefOf(el), 200) + dataHints(el) + descr(el);
    if (t === 'BUTTON' || (t === 'INPUT' && ['submit', 'button', 'reset', 'image'].includes(type)) || role === 'button') {
      const nv = el.getAttribute('name') ? ' ' + el.getAttribute('name') + '=' + (el.getAttribute('value') || '') : '';
      return tag(el, collapsed) + ' button ' + q(nameOf(el)) + nv + flags(el) + dataHints(el) + descr(el);
    }
    if (t === 'INPUT' && (type === 'checkbox' || type === 'radio'))
      return tag(el, collapsed) + ' ' + type + ' ' + q(labelOf(el)) + (el.checked ? ' [checked]' : ' [unchecked]') + (el.name ? ' name=' + el.name : '') + (el.value && el.value !== 'on' ? ' value=' + el.value : '') + flags(el);
    if (t === 'INPUT' && type === 'range')
      return tag(el, collapsed) + ' slider ' + q(labelOf(el)) + ' value=' + el.value + ' min=' + (el.min || 0) + ' max=' + (el.max || 100) + flags(el);
    if (t === 'INPUT' && type === 'file') return tag(el, collapsed) + ' file-upload ' + q(labelOf(el)) + flags(el);
    if (t === 'INPUT' || t === 'TEXTAREA') {
      const shown = type === 'password' ? (el.value ? '••••' : '') : el.value;
      return tag(el, collapsed) + ' input' + (type && type !== 'text' ? '(' + type + ')' : '') + ' ' + q(labelOf(el)) + ' value=' + q(shown) + (el.placeholder ? ' placeholder=' + q(el.placeholder) : '') + flags(el) + descr(el);
    }
    if (t === 'SELECT') {
      const options = [...el.options].slice(0, 80).map(o => (o.selected ? '*' : '') + (clean(o.textContent) === o.value ? q(o.value) : q(o.value) + '=' + q(o.textContent)));
      return tag(el, collapsed) + ' select ' + q(labelOf(el)) + flags(el) + ' options(* = selected): ' + options.join('; ') + (el.options.length > 80 ? '; …' : '');
    }
    if (t === 'SUMMARY') return null;
    if (['link', 'tab', 'menuitem', 'option', 'checkbox', 'radio', 'switch', 'treeitem'].includes(role) || el.hasAttribute('onclick') || el.isContentEditable && !el.parentElement.isContentEditable)
      return tag(el, collapsed) + ' ' + (role || 'clickable') + ' ' + q(nameOf(el)) + flags(el) + dataHints(el) + descr(el);
    return null;
  };
  const lines = [];
  let cur = '', inline = 0;
  const flush = () => { if (inline) { cur += ' '; return; } const t = cur.replace(ZW, '').replace(/[ \t ]+/g, ' ').trim(); if (t) lines.push(t); cur = ''; };
  const isBlock = el => { const d = styleOf(el).display; return !(d.startsWith('inline') || d === 'contents' || d === 'table-cell' || d === 'ruby'); };
  const isMenu = el => /^(UL|OL|MENU|DIV)$/.test(el.tagName) && !el.hidden && el.getAttribute('aria-hidden') !== 'true'
    && !!el.querySelector('a[href],button,[role=menuitem]')
    && (!!el.closest('nav,[role=navigation],[role=menubar],[role=menu]') || !!(el.previousElementSibling && el.previousElementSibling.matches('button,summary,[aria-haspopup],[aria-expanded]')));
  const walk = (node, collapsed) => {
    if (node.nodeType === 3) { cur += node.nodeValue.replace(/\s+/g, ' '); return; }
    if (node.nodeType !== 1 || SKIP.has(node.tagName)) return;
    const el = node, t = el.tagName.toUpperCase(), role = el.getAttribute('role') || '';
    if (isHidden(el)) {
      if (role === 'tooltip' || (el.id && described.has(el.id))) { if (!(el.id && described.has(el.id))) cur += ' (tooltip: ' + q(textOf(el, true)) + ') '; return; }
      if (!collapsed && cssHidden(el) && isMenu(el)) { flush(); for (const c of el.childNodes) walk(c, true); flush(); }
      return;
    }
    if (t === 'BR') { flush(); return; }
    if (t === 'HR') { flush(); return; }
    if (t === 'IFRAME' || t === 'FRAME') { flush(); const id = nextId++; el.setAttribute('data-aid', String(id)); lines.push('⟦FRAME:' + id + '⟧' + clean(el.getAttribute('title') || el.getAttribute('aria-label') || '')); return; }
    const label = el.getAttribute('aria-label');
    if (label && (role === 'img' || t === 'CANVAS' || t === 'SVG' || t === 'IMG')) { cur += ' ' + (t === 'CANVAS' ? '[canvas: ' + clean(label) + ']' : clean(label)) + ' ' + descr(el); return; }
    if (t === 'CANVAS') { const s = clean(textOf(el, false)); if (s) cur += ' [canvas: ' + s + '] '; return; }
    if (t === 'IMG') { const s = clean(el.getAttribute('alt')); if (s) cur += ' [image: ' + s + '] '; return; }
    if (t === 'SVG') { const s = clean(textOf(el, false)); if (s) cur += ' [graphic: ' + s + '] '; return; }
    if (t === 'LABEL' && (el.control || el.getAttribute('for'))) {
      // A label is announced with its control; print only controls nested inside it.
      el.querySelectorAll('input,select,textarea,button').forEach(c => { if (!isHidden(c)) { const s = control(c, collapsed); if (s) { flush(); cur += s; flush(); } } });
      return;
    }
    const asControl = control(el, collapsed);
    if (asControl) { if (isBlock(el) || t === 'SELECT') { flush(); cur += asControl; flush(); } else cur += ' ' + asControl + ' '; return; }
    const block = isBlock(el);
    if (block) flush();
    if (/^H[1-6]$/.test(t)) cur += '#'.repeat(+t[1]) + ' ';
    else if (t === 'LI') cur += '- ';
    else if (t === 'SUMMARY') cur += '▸ ';
    else if (t === 'CAPTION') cur += 'Table: ';
    else if (t === 'LEGEND') cur += '· ';
    if (role === 'status' || role === 'alert') cur += '(' + role + ') ';
    if (label && block && !['img'].includes(role)) { cur += '— ' + clean(label) + ' —'; flush(); }
    else if (label && !block && !clean(textOf(el, false)).includes(clean(label))) cur += ' {' + clean(label) + '} ';
    if (block && (el.matches('fieldset[disabled]') || el.hasAttribute('inert'))) { cur += '(LOCKED AREA: the controls below are disabled until this area is unlocked)'; flush(); }
    if (t === 'TR') {
      inline++;
      const cells = [];
      for (const cell of el.children) { if (isHidden(cell)) continue; const before = cur; cur = ''; for (const c of cell.childNodes) walk(c, collapsed); cells.push(cur.replace(/\s+/g, ' ').trim()); cur = before; }
      inline--;
      cur += cells.join(' | '); flush(); return;
    }
    if (t === 'PRE') { const pre = textOf(el, false).replace(ZW, ''); if (inline) cur += pre.replace(/\s+/g, ' '); else { flush(); pre.split('\n').forEach(l => { if (l.trim()) lines.push(l.replace(/\s+$/, '')); }); } return; }
    cur += pseudo(el, '::before');
    if (reversed(el)) cur += clean(textOf(el, false));
    else for (const c of el.childNodes) walk(c, collapsed);
    cur += pseudo(el, '::after');
    if (t === 'TIME' && el.getAttribute('datetime')) cur += ' (datetime=' + el.getAttribute('datetime') + ')';
    if ((t === 'ABBR' || t === 'SPAN' || t === 'TD' || t === 'DFN') && el.getAttribute('title')) cur += ' (title: ' + q(el.getAttribute('title')) + ')';
    if (t === 'DT') cur += ':';
    cur += descr(el);
    if (block) flush();
  };
  const modals = [...document.querySelectorAll('dialog[open],[aria-modal="true"]')].filter(d => !isHidden(d) && (d.tagName !== 'DIALOG' || d.matches(':modal')));
  for (const modal of modals) {
    lines.push('!! A MODAL DIALOG covers the page; nothing behind it works until it is dealt with:');
    walk(modal, false); flush();
    lines.push('!! END OF MODAL DIALOG. The page behind it:');
  }
  const body = document.body || document.documentElement;
  if (modals.length) { for (const c of body.childNodes) if (!modals.some(m => m === c || (c.nodeType === 1 && c.contains(m) && c === m))) walk(c, false); }
  else walk(body, false);
  flush();
  return { text: lines.join('\n'), next: nextId, title: clean(document.title) };
}
"""

# Opens collapsed sections and closes purely informational modal popups (no form controls inside): reading a page
# the model chose should not cost it a click per paragraph. Returns the popups it closed.
PREPARE_JS = r"""
() => {
  let opened = 0; const closed = [];
  document.querySelectorAll('details:not([open])').forEach(d => { d.open = true; opened++; });
  document.querySelectorAll('dialog[open]').forEach(d => {
    if (!d.matches(':modal') || d.querySelector('input:not([type=hidden]),select,textarea')) return;
    closed.push((d.getAttribute('aria-label') || (d.querySelector('h1,h2,h3') || {}).textContent || 'popup').trim().slice(0, 80));
    try { d.close(); } catch (e) {}
  });
  return { opened, closed };
}
"""

LOGIN_JS = r"""
([username, password]) => {
  const visible = el => { const cs = getComputedStyle(el); return !el.hidden && cs.display !== 'none' && cs.visibility !== 'hidden' && el.type !== 'hidden'; };
  const pass = [...document.querySelectorAll('input[type=password]')].find(visible);
  if (!pass) return 'no password field on this page';
  const scope = pass.form || document;
  const fields = [...scope.querySelectorAll('input')].filter(el => visible(el) && ['text', 'email', '', 'tel'].includes((el.getAttribute('type') || '').toLowerCase()));
  const user = fields.filter(el => el.compareDocumentPosition(pass) & Node.DOCUMENT_POSITION_FOLLOWING).pop() || fields[0];
  const set = (el, value) => { el.focus(); el.value = value; el.dispatchEvent(new Event('input', { bubbles: true })); el.dispatchEvent(new Event('change', { bubbles: true })); };
  if (user) set(user, username);
  set(pass, password);
  pass.setAttribute('data-login-password', '1');
  return 'ok';
}
"""

MAX_OBSERVATION = 14000


class _Text(HTMLParser):
    def __init__(self):
        super().__init__()
        self.parts, self.skip = [], 0

    def handle_starttag(self, tag, attrs):
        if tag in ("script", "style"):
            self.skip += 1
        elif tag in ("p", "div", "tr", "br", "li", "h1", "h2", "h3", "table"):
            self.parts.append("\n")
        elif tag in ("td", "th"):
            self.parts.append(" | ")

    def handle_endtag(self, tag):
        if tag in ("script", "style") and self.skip:
            self.skip -= 1

    def handle_data(self, data):
        if not self.skip:
            self.parts.append(data)


def clean_text(text: str) -> str:
    text = re.sub(r"[​-‏⁠-⁤﻿­͏؜᠎]", "", text)
    return re.sub(r"\n\s*\n+", "\n", re.sub(r"[ \t ]+", " ", text)).strip()


def document_text(data: bytes, content_type: str, name: str, depth: int = 0) -> str:
    """The text of a fetched file: archives are opened, markup is stripped, PDFs are read when pypdf is installed."""
    kind = (content_type or "").lower()
    lower = name.lower()
    if data[:4] == b"PK\x03\x04" or "zip" in kind or lower.endswith(".zip"):
        try:
            archive = zipfile.ZipFile(io.BytesIO(data))
        except zipfile.BadZipFile:
            return "(unreadable archive)"
        parts = [f"ARCHIVE {name} with files: " + ", ".join(info.filename for info in archive.infolist())]
        for info in archive.infolist()[:40]:
            if info.is_dir() or depth > 2:
                continue
            parts.append(f"=== FILE {info.filename} ===\n" + document_text(archive.read(info), "", info.filename, depth + 1))
        return "\n".join(parts)
    if data[:5] == b"%PDF-" or "pdf" in kind:
        try:
            from pypdf import PdfReader
            return clean_text("\n".join(page.extract_text() or "" for page in PdfReader(io.BytesIO(data)).pages))
        except Exception as error:  # noqa: BLE001
            return f"(PDF could not be read: {error})"
    text = data.decode("utf-8", errors="replace")
    if "html" in kind or "xml" in kind or re.search(r"<(html|body|table|div|p|w:document|worksheet)\b", text[:4000], re.I):
        parser = _Text()
        parser.feed(text)
        text = "".join(parser.parts)
    return clean_text(text)


class Tab:
    """One browser tab on one website, driven by one agent."""

    def __init__(self, page, site: dict):
        self.page = page
        self.site_id = site.get("siteId", "")
        self.base_url = site["url"].rstrip("/")
        self.credentials = site.get("credentials") or {}
        self.frames: list[tuple[int, int, object]] = []  # id range -> frame
        self.document = ""  # what `keep` files: the page as last read, a collected listing or a fetched file
        self.document_source = ""
        self.events: list[str] = []
        self.bad_status = 0
        page.on("dialog", lambda dialog: asyncio.ensure_future(self._on_dialog(dialog)))
        page.on("response", self._on_response)

    async def _on_dialog(self, dialog):
        self.events.append(f'the browser asked "{dialog.message}" ({dialog.type}); it was accepted')
        try:
            await dialog.accept()
        except Exception:  # noqa: BLE001
            pass

    def _on_response(self, response):
        try:
            if response.request.is_navigation_request() and response.frame == self.page.main_frame:
                self.bad_status = response.status if response.status >= 500 else 0
        except Exception:  # noqa: BLE001
            pass

    async def settle(self):
        for state, timeout in (("domcontentloaded", 15000), ("networkidle", 2500)):
            try:
                await self.page.wait_for_load_state(state, timeout=timeout)
            except Exception:  # noqa: BLE001
                pass
        for _ in range(3):  # a server error page: retry the same address, as a person would press reload
            if not self.bad_status:
                break
            self.events.append(f"the server answered HTTP {self.bad_status}; reloaded")
            await asyncio.sleep(0.4)
            try:
                await self.page.reload(wait_until="domcontentloaded", timeout=15000)
            except Exception:  # noqa: BLE001
                break

    async def _frame_text(self, frame, start: int, depth: int) -> tuple[str, int]:
        try:
            prepared = await frame.evaluate(PREPARE_JS)
            if prepared["opened"]:
                await asyncio.sleep(0.15)  # lazy content of the sections just opened
                try:
                    await self.page.wait_for_load_state("networkidle", timeout=2000)
                except Exception:  # noqa: BLE001
                    pass
            for name in prepared["closed"]:
                self.events.append(f'closed the popup "{name}"')
            shot = await frame.evaluate(SNAPSHOT_JS, start)
        except Exception as error:  # noqa: BLE001
            return f"(this document could not be read: {str(error)[:120]})", start
        self.frames.append((start, shot["next"], frame))
        text, following = shot["text"], shot["next"]
        for marker in re.findall(r"⟦FRAME:(\d+)⟧", text):
            inner = "(embedded document not loaded)"
            if depth < 4:
                try:
                    handle = await frame.query_selector(f'[data-aid="{marker}"]')
                    child = await handle.content_frame() if handle else None
                    if child:
                        try:
                            await child.wait_for_load_state("domcontentloaded", timeout=4000)
                        except Exception:  # noqa: BLE001
                            pass
                        inner, following = await self._frame_text(child, following, depth + 1)
                except Exception as error:  # noqa: BLE001
                    inner = f"(embedded document could not be read: {str(error)[:120]})"
            block = "┌── embedded document: " if inner.strip() else "┌── embedded document (empty): "
            text = text.replace(f"⟦FRAME:{marker}⟧", block, 1).replace(
                block, block, 1)
            # the marker line carries the frame's title; append the frame's content under it
            lines = text.split("\n")
            for index, line in enumerate(lines):
                if line.startswith(block) and not line.endswith("⁣"):
                    lines[index] = line + "⁣"
                    lines.insert(index + 1, "\n".join("│ " + row for row in inner.split("\n")) + "\n└── end of embedded document")
                    break
            text = "\n".join(lines)
        return text.replace("⁣", ""), following

    async def read(self) -> str:
        """The current page as text, with fresh element ids."""
        await self.settle()
        self.frames = []
        text, _ = await self._frame_text(self.page.main_frame, 1, 0)
        try:
            title = await self.page.title()
        except Exception:  # noqa: BLE001
            title = ""
        self.document = clean_text(text)
        self.document_source = self.page.url
        return f"url: {self.page.url}\ntitle: {clean_text(title)}\n{self.document}"

    async def observe(self) -> str:
        text = await self.read()
        if len(text) > MAX_OBSERVATION:
            text = text[:MAX_OBSERVATION] + f"\n… (page text cut here; {len(text) - MAX_OBSERVATION} more characters. `keep` files the whole page.)"
        return text

    def take_events(self) -> list[str]:
        events, self.events = self.events, []
        return events

    def _locator(self, aid):
        try:
            number = int(aid)
        except (TypeError, ValueError):
            return None
        for start, end, frame in self.frames:
            if start <= number < end:
                return frame.locator(f'[data-aid="{number}"]')
        return None

    async def _describe(self, locator) -> dict:
        return await locator.evaluate(
            """el => ({tag: el.tagName, type: (el.getAttribute('type') || '').toLowerCase(), href: el.href || '',
                      disabled: el.disabled === true || !!el.closest('fieldset[disabled],[inert]'),
                      name: (el.innerText || el.value || el.getAttribute('aria-label') || '').replace(/\\s+/g, ' ').trim().slice(0, 80)})""")

    async def click(self, aid) -> str:
        locator = self._locator(aid)
        if locator is None or await locator.count() == 0:
            return f"there is no element [{aid}] on the page any more; read the current page"
        info = await self._describe(locator)
        if info["disabled"]:
            return f"[{aid}] is disabled (inside a locked or inert area?); nothing happened"
        before = self.page.url
        try:
            await locator.click(timeout=2500)
        except Exception:  # noqa: BLE001  hidden in a collapsed menu, or covered: activate it directly
            try:
                await locator.evaluate("el => el.click()")
            except Exception as error:  # noqa: BLE001
                return f"could not click [{aid}]: {str(error)[:150]}"
        await self.settle()
        moved = self.page.url != before
        return f'clicked [{aid}] "{info["name"]}"' + (f"; now at {self.page.url}" if moved else "")

    async def fill(self, aid, text: str, enter: bool = False) -> str:
        locator = self._locator(aid)
        if locator is None or await locator.count() == 0:
            return f"there is no element [{aid}] on the page any more"
        try:
            await locator.fill(str(text), timeout=2500)
        except Exception as error:  # noqa: BLE001
            return f"could not fill [{aid}]: {str(error)[:150]}"
        if enter:
            await locator.press("Enter")
            await self.settle()
        return f"filled [{aid}]" + (" and pressed Enter" if enter else "")

    async def select(self, aid, value: str) -> str:
        locator = self._locator(aid)
        if locator is None or await locator.count() == 0:
            return f"there is no element [{aid}] on the page any more"
        wanted = str(value)
        for attempt in ({"value": wanted}, {"label": wanted}):
            try:
                await locator.select_option(timeout=2000, **attempt)
                await self.settle()
                return f'selected "{wanted}" in [{aid}]'
            except Exception:  # noqa: BLE001
                continue
        options = await locator.evaluate("el => [...(el.options || [])].map(o => o.value + '=' + o.textContent.trim())")
        loose = [o.split("=", 1)[0] for o in options if wanted.lower() in o.lower()]
        if len(loose) == 1:
            await locator.select_option(value=loose[0])
            await self.settle()
            return f'selected "{loose[0]}" in [{aid}]'
        return f'[{aid}] has no option "{wanted}"; options: {"; ".join(options)[:600]}'

    async def set(self, aid, value) -> str:
        locator = self._locator(aid)
        if locator is None or await locator.count() == 0:
            return f"there is no element [{aid}] on the page any more"
        info = await self._describe(locator)
        if info["disabled"]:
            return f"[{aid}] is disabled; nothing happened"
        try:
            if info["type"] in ("checkbox", "radio"):
                await locator.set_checked(bool(value), timeout=2500, force=True)
            else:  # a slider or another input whose value is set in one go
                await locator.evaluate(
                    """(el, v) => { const proto = Object.getPrototypeOf(el); const d = Object.getOwnPropertyDescriptor(proto, 'value');
                                   d && d.set ? d.set.call(el, String(v)) : el.value = String(v);
                                   el.dispatchEvent(new Event('input', {bubbles: true})); el.dispatchEvent(new Event('change', {bubbles: true})); }""",
                    value)
        except Exception as error:  # noqa: BLE001
            return f"could not set [{aid}]: {str(error)[:150]}"
        await self.settle()
        return f"set [{aid}] to {value}"

    def _on_site(self, url: str) -> bool:
        return urlparse(url).netloc == urlparse(self.base_url).netloc

    async def goto(self, url: str) -> str:
        target = urljoin(self.page.url if self._on_site(self.page.url) else self.base_url + "/", str(url).strip())
        if not self._on_site(target):
            return f"{target} is not on this website; you only work on {self.base_url}"
        try:
            await self.page.goto(target, wait_until="domcontentloaded", timeout=20000)
        except Exception as error:  # noqa: BLE001
            return f"could not open {target}: {str(error)[:150]}"
        await self.settle()
        return f"opened {self.page.url}"

    async def back(self) -> str:
        try:
            await self.page.go_back(wait_until="domcontentloaded", timeout=15000)
        except Exception as error:  # noqa: BLE001
            return f"could not go back: {str(error)[:120]}"
        await self.settle()
        return f"went back to {self.page.url}"

    async def reload(self) -> str:
        try:
            await self.page.reload(wait_until="domcontentloaded", timeout=15000)
        except Exception as error:  # noqa: BLE001
            return f"could not reload: {str(error)[:120]}"
        await self.settle()
        return "reloaded the page"

    async def login(self) -> str:
        if not self.credentials.get("password"):
            return "there are no credentials for this website"
        outcome = "no password field on this page"
        for frame in self.page.frames:
            try:
                outcome = await frame.evaluate(LOGIN_JS, [self.credentials.get("username", ""), self.credentials["password"]])
            except Exception:  # noqa: BLE001
                continue
            if outcome == "ok":
                await frame.locator("[data-login-password]").first.press("Enter")
                await self.settle()
                return f"entered the credentials and submitted the login form; now at {self.page.url}"
        return outcome

    async def collect(self, aid, max_pages: int = 10) -> str:
        """Follow the paging control the model chose until it is gone, and return every page as one document."""
        locator = self._locator(aid)
        if locator is None or await locator.count() == 0:
            return f"there is no element [{aid}] on the page any more"
        info = await self._describe(locator)
        if not info["name"]:
            return f"[{aid}] has no label to follow from page to page"
        first = self.document
        pages, seen = [first], {first}
        for _ in range(max(1, min(int(max_pages or 10), 30)) - 1):
            control = None
            for _, _, frame in self.frames:
                candidates = frame.locator("a[href], button, [role=button], [role=link]")
                for index in range(min(await candidates.count(), 200)):
                    candidate = candidates.nth(index)
                    try:
                        label = clean_text(await candidate.evaluate("el => el.innerText || el.value || el.getAttribute('aria-label') || ''"))
                        if label == info["name"] and (await candidate.evaluate("el => el.tagName")) == info["tag"] \
                                and not await candidate.evaluate("el => el.disabled === true"):
                            control = candidate
                            break
                    except Exception:  # noqa: BLE001
                        continue
                if control:
                    break
            if control is None:
                break
            try:
                await control.click(timeout=2500)
            except Exception:  # noqa: BLE001
                try:
                    await control.evaluate("el => el.click()")
                except Exception:  # noqa: BLE001
                    break
            await self.read()
            if self.document in seen:
                break
            seen.add(self.document)
            pages.append(self.document)
        grows = len(pages) > 1 and all(later.startswith(pages[0][:200]) and len(later) >= len(earlier)
                                       for earlier, later in zip(pages, pages[1:])) and info["tag"] != "A"
        if grows:  # a "load more" control: the last page holds every row
            self.document = pages[-1]
            return f'followed "{info["name"]}" {len(pages) - 1} time(s); the list is now complete on the page'
        self.document = "\n".join(f"===== page {number} of the collected list =====\n{page}" for number, page in enumerate(pages, 1))
        return (f'followed "{info["name"]}" through {len(pages)} page(s). COLLECTED DOCUMENT (file it with keep if it '
                f"is relevant; the element ids below are only valid for the last page):\n{self.document[:MAX_OBSERVATION * 2]}")

    async def fetch(self, aid) -> str:
        """Download what the chosen link points to and read it as a document."""
        locator = self._locator(aid)
        if locator is None or await locator.count() == 0:
            return f"there is no element [{aid}] on the page any more"
        target = await locator.evaluate("el => el.href || el.src || el.getAttribute('data-url') || el.getAttribute('formaction') || ''")
        if not target:
            return f"[{aid}] has no address to download"
        target = urljoin(self.page.url, target)
        if not self._on_site(target):
            return f"{target} is not on this website"
        try:
            response = await self.page.context.request.get(target, timeout=20000)
            data = await response.body()
        except Exception as error:  # noqa: BLE001
            return f"could not download {target}: {str(error)[:150]}"
        name = urlparse(target).path.rsplit("/", 1)[-1] or "download"
        disposition = response.headers.get("content-disposition", "")
        named = re.search(r'filename\*?=(?:UTF-8\'\')?"?([^";]+)', disposition)
        if named:
            name = named.group(1)
        self.document = document_text(data, response.headers.get("content-type", ""), name)
        self.document_source = target
        return (f"downloaded {name} (HTTP {response.status}, {len(data)} bytes). DOCUMENT (file it with keep if it is "
                f"relevant):\n{self.document[:MAX_OBSERVATION * 2]}")

"""The agent loop: a model reads a browser tab as text, decides what to do next, and acts.

One `Agent` drives one `Tab`. Each turn the model gets its briefing, what its last actions did and the current page,
and answers with a thought and a short list of actions. The loop only carries those out; where to go, what to
search for, which record matters and when the job is finished are the model's calls.
"""
from __future__ import annotations

import asyncio
import json
import time
from typing import Awaitable, Callable

import llm
from browser_env import Tab

ACTIONS_HELP = """Reply with ONE JSON object: {"thought": "<short reasoning>", "actions": [ ... ]}.
The actions run in order. Once an action loads another page the rest of the list is dropped, because the element
ids change with every page: chain actions only while you stay on the page (fill fields, tick boxes, then click).
Elements you can act on carry an id like [12].

Browser actions:
  {"do": "login"}                                  enter this website's credentials in the login form shown and submit it
  {"do": "click", "id": 12}
  {"do": "fill", "id": 12, "text": "...", "enter": false}     type into a field; "enter": true also presses Enter
  {"do": "select", "id": 12, "value": "<an option's value or label>"}
  {"do": "set", "id": 12, "value": true}           tick/untick a checkbox, choose a radio button, or move a slider to a number
  {"do": "goto", "url": "<an address or path on this website that you have seen>"}
  {"do": "back"}    {"do": "reload"}
  {"do": "collect", "id": 12, "max_pages": 10}     [12] is the next-page or load-more control of a list or paged document you want in full: it is followed until the end and all pages come back as one document
  {"do": "fetch", "id": 12}                        download the file behind link [12] (archive, CSV, PDF, text) and read it as a document
  {"do": "wait"}                                   nothing to do right now
  {"do": "done", "summary": "...", "answer": "..."}   you are finished; "answer" only when you were asked for one

Reading the page:
- It is rendered as a screen reader would read it. "(described: ...)" and "(tooltip: ...)" hold text that only
  shows on hover, "[canvas: ...]" what a drawing says, "(in collapsed menu)" an entry of a menu that is closed
  (you can click it all the same), "->" where a link leads, "{data-...}" attributes of a control.
- A "LOCKED AREA" is disabled until you pass the check in front of it.
- Several controls can carry the same name while only one of them does the job: tell them apart by where they
  lead and what their attributes say.
- Popups, cookie walls, access checks, error pages and expired sessions happen. Deal with them and carry on;
  after a session expires, log in again. Surveys, tools and help pages lead away from your task.
"""

FULL_TURNS = 2  # how many past turns stay word for word; older ones keep the reasoning and drop the page text
NAVIGATING = {"click", "goto", "back", "reload", "login", "collect", "fetch"}


class Agent:
    def __init__(self, name: str, tab: Tab, system: str, briefing: Callable[[], str],
                 extra: dict[str, Callable[[dict], Awaitable[str]]] | None = None, deadline: float | None = None,
                 max_steps: int = 80, think: bool = True,
                 idle: Callable[[str], Awaitable[str | None]] | None = None):
        """`briefing()` heads every turn. `extra` adds actions: name -> handler(action) -> result text.
        `idle("wait" | "done")` lets the caller hold the agent until there is news (returns the news) or let it
        stop (returns None)."""
        self.name, self.tab, self.system, self.briefing = name, tab, system, briefing
        self.extra = extra or {}
        self.deadline = deadline or time.time() + 3600
        self.max_steps, self.think, self.idle = max_steps, think, idle
        self.turns: list[dict] = []
        self.held: tuple[str, str] | None = None  # a collected or fetched document, until the agent moves on
        self.steps = 0

    def document(self) -> tuple[str, str]:
        """What the agent is looking at: the document it collected or fetched, else the page as last read."""
        return self.held or (self.tab.document, self.tab.document_source)

    def log(self, text: str) -> None:
        print(f"[{self.name} {self.steps:02d}] {text}", flush=True)

    def _messages(self, user: str) -> list[dict]:
        messages = [{"role": "system", "content": self.system}]
        for index, turn in enumerate(self.turns):
            recent = index >= len(self.turns) - FULL_TURNS
            messages.append({"role": "user", "content": turn["user"] if recent else turn["short"]})
            messages.append({"role": "assistant", "content": turn["assistant"]})
        messages.append({"role": "user", "content": user})
        return messages

    async def _browser(self, action: dict) -> str:
        do, tab = action.get("do"), self.tab
        if do == "login":
            return await tab.login()
        if do == "click":
            return await tab.click(action.get("id"))
        if do == "fill":
            return await tab.fill(action.get("id"), action.get("text", ""), bool(action.get("enter")))
        if do == "select":
            return await tab.select(action.get("id"), action.get("value", ""))
        if do == "set":
            return await tab.set(action.get("id"), action.get("value", True))
        if do == "goto":
            return await tab.goto(action.get("url", ""))
        if do == "back":
            return await tab.back()
        if do == "reload":
            return await tab.reload()
        if do == "collect":
            return await tab.collect(action.get("id"), action.get("max_pages") or 10)
        if do == "fetch":
            return await tab.fetch(action.get("id"))
        return f'unknown action "{do}"'

    async def _alive(self) -> bool:
        try:
            return bool(await self.tab.page.main_frame.evaluate("() => document.querySelectorAll('[data-aid]').length > 0"))
        except Exception:  # noqa: BLE001
            return False

    async def run(self) -> dict:
        results: list[str] = []
        outcome = {"done": False, "summary": "", "answer": None, "steps": 0}
        if self.tab.page.url in ("", "about:blank"):
            results.append(await self.tab.goto(self.tab.base_url + "/"))
        repeats, last_signature, failures = 0, "", 0
        while self.steps < self.max_steps and time.time() < self.deadline:
            self.steps += 1
            try:
                page = await self.tab.observe()
            except Exception as error:  # noqa: BLE001
                page = f"(the page could not be read: {str(error)[:200]})"
            results.extend(self.tab.take_events())
            done_text = "\n".join(f"{n}. {text}" for n, text in enumerate(results, 1)) or "(none yet)"
            left = int(self.deadline - time.time())
            user = (f"{self.briefing()}\n\nTIME LEFT: {left} s\n\nRESULTS OF YOUR LAST ACTIONS\n{done_text}\n\n"
                    f"CURRENT PAGE\n{page}")
            reply = await llm.chat_json(self._messages(user), think=self.think, label=self.name)
            actions = reply.get("actions")
            if isinstance(actions, dict):
                actions = [actions]
            if not isinstance(actions, list) or not actions:
                failures += 1
                if failures >= 4:
                    self.log("the model gave no usable actions four times; stopping")
                    break
                results = ['your reply had no "actions" list; reply with {"thought": ..., "actions": [...]}']
                continue
            failures = 0
            thought = str(reply.get("thought", ""))[:300]
            head = page.split("\n", 2)
            short = f"RESULTS OF YOUR LAST ACTIONS\n{done_text[:700]}\n\nPAGE (text dropped)\n" + "\n".join(head[:2])
            self.turns.append({"user": user, "short": short, "assistant": json.dumps(reply, ensure_ascii=False)})

            signature = json.dumps(actions, sort_keys=True) + self.tab.page.url
            repeats = repeats + 1 if signature == last_signature else 0
            last_signature = signature

            results, finished, moved = [], None, False
            for action in actions[:8]:
                if not isinstance(action, dict):
                    continue
                do = action.get("do")
                if do == "done":
                    finished = action
                    break
                if do == "wait":
                    news = await self.idle("wait") if self.idle else None
                    if news is None and not self.idle:
                        await asyncio.sleep(2)
                    results.append(news or "waited")
                    continue
                if do in self.extra:
                    try:
                        results.append(await self.extra[do](action))
                    except Exception as error:  # noqa: BLE001
                        results.append(f"{do} failed: {str(error)[:200]}")
                    continue
                if moved:
                    results.append(f'skipped {json.dumps(action, ensure_ascii=False)[:120]}: the page changed, its ids are stale')
                    continue
                before = self.tab.page.url
                try:
                    result = await self._browser(action)
                except Exception as error:  # noqa: BLE001
                    result = f"{do} failed: {str(error)[:200]}"
                results.append(result)
                if do in ("collect", "fetch"):
                    self.held = (self.tab.document, self.tab.document_source)
                elif do in NAVIGATING:
                    self.held = None
                if do in NAVIGATING or self.tab.page.url != before or not await self._alive():
                    moved = True
            self.log(f"{thought} | {json.dumps(actions, ensure_ascii=False)[:400]} | " + " ; ".join(r[:160] for r in results))
            if repeats >= 2:
                results.append("You have sent the same actions three times with the same result. Do something "
                               "different, or finish with done.")
            if finished is not None:
                outcome.update(summary=str(finished.get("summary", "")), answer=finished.get("answer"))
                news = await self.idle("done") if self.idle else None
                if news is None:
                    outcome["done"] = True
                    break
                results.append(news)
        outcome["steps"] = self.steps
        return outcome

